parts.script:
// current date/time — plain JS, nothing special
const now = new Date();
const iso = now.toISOString();
const readable = now.toLocaleString();
ctx.log('current time: ' + readable);
return { value: { iso, readable, tick: ctx.tick }, state: {}, leftBadge: { text: readable, color: '#2f8f4e' } };

// ctx.part is this node's own Part record — its identity, not incoming data
const info = { id: ctx.part.id, type: ctx.part.type, label: ctx.part.label, model: ctx.part.model };
ctx.log('I am "' + ctx.part.label + '" of type ' + ctx.part.type);
return { value: info, state: {}, leftBadge: { text: info.type, color: '#2f8f4e' } };

// declare new local variables, then put them in the RETURNED value — that return
// value is the outgoing packet every downstream connector will see as their input
let counter = (ctx.state.counter || 0) + 1;
const tag = 'batch-' + counter;
const payload = { counter, tag, generatedAt: new Date().toISOString() };
ctx.log('emitting packet ' + tag);
return { value: payload, state: { counter }, leftBadge: { text: tag, color: '#2f8f4e' } };

// ctx.inputs is an array — one entry per incoming connector this tick.
// value is undefined until the upstream node has actually produced something.
if (ctx.inputs.length === 0) return { value: null, state: {} };
const incoming = ctx.inputs[0].value;
if (!incoming) return { value: null, state: {} };

// read fields off the incoming packet
const receivedTag = incoming.tag;
const receivedCounter = incoming.counter;

// a NEW variable of this node's own
const receivedAt = new Date().toISOString();

ctx.log('received ' + receivedTag + ' (counter=' + receivedCounter + ') from ' + ctx.inputs[0].fromLabel);

// fold the new variable INTO the outgoing packet, alongside everything received
return { value: { ...incoming, receivedAt, receivedBy: ctx.part.label }, state: {}, leftBadge: { text: receivedTag, color: '#2f8f4e' } };
